const crypto = require('crypto');

const isConfirmation = ($json.webhookUrl ?? '')
  .endsWith('/taxi-driver-response');

const token = isConfirmation
  ? $json.body?.token
  : $json.query?.token;

const validTokenFormat =
  typeof token === 'string' &&
  /^[a-f0-9]{64}$/.test(token);

return {
  json: {
    requestMode: isConfirmation ? 'confirm' : 'preview',
    validTokenFormat,
    token: validTokenFormat ? token : null,
    tokenHash: validTokenFormat
      ? crypto.createHash('sha256').update(token).digest('hex')
      : null
  }
};

