const operation = $('Rezervo përpunimin e vendimit')
  .first().json.operation;

const record = $('Lexo udhëtimin për konfirmim')
  .first().json;

const trip = record.fields ?? record;
const city = String(trip.Qyteti ?? '').trim();

const history = $input.first().json.excluded_driver_ids;

if (!city) {
  throw new Error('Udhëtimit i mungon qyteti.');
}

if (!Array.isArray(history)) {
  throw new Error('Lista e shoferëve që refuzuan nuk është e vlefshme.');
}

const excludedDriverIds = [
  ...new Set([...history, operation.driver_id])
];

const conditions = [
  '{Statusi}="I LIRË"',
  `{Qyteti}=${JSON.stringify(city)}`,
  ...excludedDriverIds.map(
    id => `NOT(RECORD_ID()=${JSON.stringify(id)})`
  )
];

return [{
  json: {
    tripId: operation.trip_id,
    city,
    excludedDriverIds,
    filterFormula: `AND(${conditions.join(',')})`
  }
}];

const items = $input.all();

const context = $('Përgatit kërkimin e shoferit zëvendësues')
  .first().json;

const rawTrip = $('Lexo udhëtimin për konfirmim')
  .first().json;

const trip = rawTrip.fields ?? rawTrip;
const customerId = trip.Klienti?.[0];

if (!customerId) {
  throw new Error('Udhëtimit i mungon lidhja me klientin.');
}

const candidateIds = [...new Set(
  items
    .map(item => item.json)
    .filter(record => {
      const fields = record.fields ?? record;

      return record.id
        && fields.Statusi === 'I LIRË'
        && String(fields.Qyteti ?? '').trim() === context.city
        && !context.excludedDriverIds.includes(record.id);
    })
    .map(record => record.id)
)];

return [{
  json: {
    ...context,
    customerId,
    candidateIds,
    candidateCount: candidateIds.length
  },
  pairedItem: items.map((_, item) => ({ item }))
}];

const context = $input.first().json;

return context.candidateIds.map(driverId => ({
  json: {
    tripId: context.tripId,
    candidateDriverId: driverId,
    newAssignmentId: `assignment-${$execution.id}`
  },
  pairedItem: { item: 0 }
}));

const result = $input.first().json;
const reservation = result.reservation;

if (
  result.claimed !== true ||
  !reservation?.driver_id ||
  !reservation?.trip_id ||
  !reservation?.assignment_id
) {
  throw new Error('Mungojnë të dhënat e rezervimit të ri.');
}

return [{
  json: {
    driverId: reservation.driver_id,
    tripId: reservation.trip_id,
    assignmentId: reservation.assignment_id
  },
  pairedItem: { item: 0 }
}];

const tokens = $input.first().json;
const assignment = $('Ruaj caktimin e ri').first().json;
const context = $('Përgatit kandidatët për ricaktim')
  .first().json;

const validToken = value =>
  typeof value === 'string' &&
  /^[a-f0-9]{64}$/.test(value);

if (
  tokens.tokens_created !== 2 ||
  !validToken(tokens.accept_token) ||
  !validToken(tokens.refuse_token)
) {
  throw new Error('Dy tokenët e caktimit të ri nuk u krijuan.');
}

const confirmationUrl =
  'https://aulon10.app.n8n.cloud/webhook-test/taxi-driver-confirm';

return [{
  json: {
    ...assignment,
    customerId: context.customerId,
    acceptUrl:
      `${confirmationUrl}?token=${tokens.accept_token}`,
    refuseUrl:
      `${confirmationUrl}?token=${tokens.refuse_token}`,
    expiresAt: tokens.expires_at
  },
  pairedItem: { item: 0 }
}];

const fields = record => record.fields ?? record;

const driver = fields(
  $('Lexo shoferin zëvendësues').first().json
);

const customer = fields(
  $('Lexo klientin për ricaktim').first().json
);

const trip = fields(
  $('Lexo udhëtimin për konfirmim').first().json
);

const links = $('Përgatit linket e shoferit zëvendësues')
  .first().json;

function required(value, label) {
  const text = String(value ?? '').trim();
  if (!text) {
    throw new Error(`Mungon: ${label}`);
  }
  return text;
}

const to = required(driver.Email, 'email-i i shoferit');
const driverName = required(driver['Emri i plotë'], 'emri i shoferit');
const customerName = required(customer['Emri i klientit'], 'emri i klientit');
const phone = required(customer['Numri i telefonit'], 'telefoni i klientit');
const city = required(trip.Qyteti, 'qyteti');
const pickup = required(trip['Lokacioni i marrjes'], 'lokacioni i marrjes');
const destination = required(trip.Destinacioni, 'destinacioni');

const subject = trip['Udhëtimi']
  ? `Kërkesë për udhëtimin ${trip['Udhëtimi']}`
  : 'Kërkesë e re për udhëtim';

const message = [
  `Përshëndetje ${driverName},`,
  '',
  'Ke një kërkesë të re për udhëtim:',
  '',
  `Klienti: ${customerName}`,
  `Telefoni: ${phone}`,
  `Qyteti: ${city}`,
  `Nisja: ${pickup}`,
  `Destinacioni: ${destination}`,
  '',
  'PRANO udhëtimin:',
  links.acceptUrl,
  '',
  'REFUZO udhëtimin:',
  links.refuseUrl,
  '',
  'Hape linkun përkatës dhe konfirmo vendimin në faqen që shfaqet.'
].join('\n');

return [{
  json: {
    ...links,
    to,
    subject,
    message
  },
  pairedItem: { item: 0 }
}];

const customerRecord = $input.first().json;
const customer = customerRecord.fields ?? customerRecord;

const tripRecord = $('Lexo udhëtimin për konfirmim')
  .first().json;
const trip = tripRecord.fields ?? tripRecord;

function required(value, label) {
  const text = String(value ?? '').trim();
  if (!text) {
    throw new Error(`Mungon: ${label}`);
  }
  return text;
}

const to = required(customer.Email, 'email-i i klientit');
const name = required(customer['Emri i klientit'], 'emri i klientit');
const city = required(trip.Qyteti, 'qyteti');
const pickup = required(trip['Lokacioni i marrjes'], 'lokacioni i marrjes');
const destination = required(trip.Destinacioni, 'destinacioni');

return [{
  json: {
    to,
    subject: 'Njoftim për kërkesën tënde për taksi',
    message: [
      `Përshëndetje ${name},`,
      '',
      `Aktualisht nuk gjetëm një shofer tjetër të lirë në ${city}.`,
      'Kërkesa jote mbetet në pritje të caktimit të një shoferi.',
      '',
      `Nisja: ${pickup}`,
      `Destinacioni: ${destination}`
    ].join('\n')
  },
  pairedItem: { item: 0 }
}];

const tokens = $('Krijo tokenin e fillimit').first().json;
const driverRecord = $input.first().json;
const driver = driverRecord.fields ?? driverRecord;

const tripRecord = $('Lexo udhëtimin për konfirmim')
  .first().json;
const trip = tripRecord.fields ?? tripRecord;

if (
  tokens.tokens_created !== 1 ||
  typeof tokens.start_token !== 'string' ||
  !/^[a-f0-9]{64}$/.test(tokens.start_token)
) {
  throw new Error('Tokeni i fillimit nuk u krijua.');
}

function required(value, label) {
  const text = String(value ?? '').trim();
  if (!text) {
    throw new Error(`Mungon: ${label}`);
  }
  return text;
}

const to = required(driver.Email, 'email-i i shoferit');
const name = required(driver['Emri i plotë'], 'emri i shoferit');
const pickup = required(trip['Lokacioni i marrjes'], 'nisja');
const destination = required(trip.Destinacioni, 'destinacioni');

const startUrl =
  'https://aulon10.app.n8n.cloud/webhook-test/taxi-trip-start-confirm'
  + '?token=' + tokens.start_token;

return [{
  json: {
    to,
    subject: 'Konfirmimi i fillimit të udhëtimit',
    message: [
      `Përshëndetje ${name},`,
      '',
      'Pranimi i udhëtimit u regjistrua.',
      `Nisja: ${pickup}`,
      `Destinacioni: ${destination}`,
      '',
      'Kur ta fillosh udhëtimin, hape këtë link dhe zgjidh PO:',
      startUrl,
      '',
      'Nëse ende nuk ke filluar, zgjidh JO.'
    ].join('\n')
  },
  pairedItem: { item: 0 }
}];
